import org.jsoup.Connection;
import org.jsoup.helper.UrlBuilder;
import org.jsoup.helper.StringUtil;
import org.junit.Test;

import java.net.MalformedURLException;
import java.net.URL;

import static org.junit.Assert.assertEquals;

public class UrlBuilderTests {

    @Test
    public void buildWithoutQueryTest() throws MalformedURLException {
        URL inputUrl = new URL("http://www.example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        assertEquals(new URL("http://www.example.com"), urlBuilder.build());
    }

    @Test
    public void buildWithQueryTest() throws Exception {
        URL inputUrl = new URL("http://www.example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        urlBuilder.appendKeyVal(new Connection.KeyVal("name", "value"));
        assertEquals(new URL("http://www.example.com?name=value"), urlBuilder.build());
    }

    @Test
    public void buildWithMultipleQueriesTest() throws Exception {
        URL inputUrl = new URL("http://www.example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        urlBuilder.appendKeyVal(new Connection.KeyVal("name1", "value1"));
        urlBuilder.appendKeyVal(new Connection.KeyVal("name2", "value2"));
        assertEquals(new URL("http://www.example.com?name1=value1&name2=value2"), urlBuilder.build());
    }

    @Test
    public void buildWithSpecialCharactersTest() throws Exception {
        URL inputUrl = new URL("http://www.example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        urlBuilder.appendKeyVal(new Connection.KeyVal("?@#^$& ", "%20+"));
        assertEquals(new URL("http://www.example.com?%3F%40%23%5E%24%26%20=%2520%2B"), urlBuilder.build());
    }
}
